data-bs-toggle="modal" data-bs-target="#tripViewModal" data-item="{{base64_encode(json_encode($d))}}" onclick="viewTrip(this.dataset.item)" title="View">{!!$svg['view']!!}</button><button class="trip-action" data-bs-toggle="modal" data-bs-target="#tripFormModal" data-item="{{base64_encode(json_encode($d))}}" onclick="openTrip(this.dataset.item)" title="Edit">{!!$svg['edit']!!}</button><button class="trip-action" data-bs-toggle="modal" data-bs-target="#tripStatusModal" data-item="{{base64_encode(json_encode($d))}}" onclick="statusTrip(this.dataset.item)" title="Status">{!!$svg['status']!!}</button><button class="trip-action" data-bs-toggle="modal" data-bs-target="#tripFinanceModal" data-item="{{base64_encode(json_encode($d))}}" onclick="financeTrip(this.dataset.item)" title="Advance & Expenses">{!!$svg['money']!!}</button>@if($t->document_path)<a class="trip-action" target="_blank" href="{{route('trips-document',$t)}}">{!!$svg['doc']!!}</a>@endif<form method="POST" action="{{route('trips-destroy',$t)}}" class="trip-delete">@csrf @method('DELETE')<button class="trip-action">{!!$svg['delete']!!}</button></form></div></td></tr>@empty<tr><td colspan="8" class="text-center py-10 text-muted">No trips found.</td></tr>@endforelse</tbody></table></div><div class="d-flex justify-content-between align-items-center p-5"><span class="text-muted">Showing {{$trips->firstItem()??0}} to {{$trips->lastItem()??0}} of {{$trips->total()}} results</span>{{$trips->links('pagination::bootstrap-4')}}</div></div></div>
