<script>const tripRoutes={store:@json(route('trips-store')),update:@json(route('trips-update','__ID__')),status:@json(route('trips-status','__ID__')),finance:@json(route('trips-finance','__ID__'))};function tripData(x){return x?JSON.parse(atob(x)):{} }function openTrip(x){let d=tripData(x),f=tripForm;f.reset();f.action=tripRoutes.store;tripMethod.innerHTML='';tripTitle.textContent=d.id?'Edit Trip':'Add New Trip';['employee_id','purpose','destination','start_date','end_date','description','expected_outcomes','advance_amount'].forEach(k=>f.elements[k].value=d[k]||'');if(d.id){f.action=tripRoutes.update.replace('__ID__',d.id);tripMethod.innerHTML='<input type="hidden" name="_method" value="PUT">'}}function viewTrip(x){let d=tripData(x),m=tripViewModal,v={purpose:d.purpose,destination:d.destination,start:d.start_date,end:d.end_date,status:d.status,advance:d.advance_amount?'৳'+Number(d.advance_amount).toLocaleString(undefined,{minimumFractionDigits:2}):'—',expense:d.expense_amount?'৳'+Number(d.expense_amount).toLocaleString(undefined,{minimumFractionDigits:2}):'—',description:d.description,outcomes:d.expected_outcomes};Object.keys(v).forEach(k=>m.querySelector('[data-trip-view='+k+']').textContent=v[k]||'—');m.querySelector('[data-trip-view=document]').innerHTML=d.document_url?(/\.(png|jpe?g)$/i.test(d.document_path)?'<a target="_blank" href="'+d.document_url+'"><img class="trip-preview" src="'+d.document_url+'"></a>':'<a target="_blank" href="'+d.document_url+'">View document</a>'):'—'}function statusTrip(x){let d=tripData(x),f=tripStatusForm;f.action=tripRoutes.status.replace('__ID__',d.id);f.elements.status.value=d.status}function financeTrip(x){let d=tripData(x),f=tripFinanceForm;f.action=tripRoutes.finance.replace('__ID__',d.id);['advance_amount','advance_status','expense_amount','expense_status'].forEach(k=>f.elements[k].value=d[k]||'')}document.addEventListener('DOMContentLoaded',()=>{tripForm.onsubmit=e=>{let req={employee_id:'Employee',purpose:'Purpose',destination:'Destination',start_date:'Start Date',end_date:'End Date'},miss=Object.entries(req).find(([k])=>!tripForm.elements[k].value);if(!miss&&tripForm.elements.end_date.value<tripForm.elements.start_date.value)miss=['end_date','End Date must be after Start Date'];if(miss){e.preventDefault();Swal.fire({icon:'error',text:miss[1]+(miss[0]==='end_date'&&miss[1].includes('must')?'':' is required')})}};document.querySelectorAll('.trip-delete').forEach(f=>f.onsubmit=e=>{if(f.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete trip?',text:'This action cannot be undone.',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f1416c'}).then(r=>{if(r.isConfirmed){f.dataset.ok=1;f.submit()}})})})</script>
<script>
document.addEventListener('DOMContentLoaded',function(){
 var expenseUrl=@json(route('trip-expenses-index','__ID__'));
 document.querySelectorAll('.trip-table tbody tr').forEach(function(row){
  var view=row.querySelector('.trip-action[title="View"]');if(!view)return;
  var d=tripData(view.dataset.item),actions=view.closest('.d-flex'),deleteForm=actions.querySelector('.trip-delete');
  var expense=document.createElement('a');expense.className='trip-action';expense.title='Trip Expenses';expense.href=expenseUrl.replace('__ID__',d.id);expense.innerHTML='<svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h4"/></svg>';
  var toggle=document.createElement('button');toggle.type='button';toggle.className='trip-action btn btn-sm btn-light';toggle.title='Expand Details';toggle.innerHTML='⌄';
  actions.insertBefore(expense,deleteForm);actions.appendChild(toggle);
  var advance=Number(d.advance_amount||0),spent=Number(d.expense_amount||0),net=advance-spent,details=document.createElement('tr');details.style.display='none';details.innerHTML='<td colspan="8" class="p-5 bg-light"><div class="card p-5"><div class="row g-5"><div class="col-md-4 border-end"><h4 class="mb-4 text-success">♙ &nbsp; Trip Details</h4><div class="row g-2"><span class="col-5 text-muted">Employee</span><strong class="col-7">'+(d.employee||'—')+'</strong><span class="col-5 text-muted">Destination</span><strong class="col-7">'+(d.destination||'—')+'</strong><span class="col-5 text-muted">Start Date</span><strong class="col-7">'+d.start_date+'</strong><span class="col-5 text-muted">End Date</span><strong class="col-7">'+d.end_date+'</strong><span class="col-5 text-muted">Trip Status</span><strong class="col-7">'+d.status+'</strong></div></div><div class="col-md-4 border-end"><h4 class="mb-4 text-success">৳ &nbsp; Financial Summary</h4><div class="d-flex justify-content-between mb-2"><span class="text-muted">Advance</span><strong>৳'+advance.toLocaleString(undefined,{minimumFractionDigits:2})+'</strong></div><div class="d-flex justify-content-between mb-2"><span class="text-muted">Expenses</span><strong>৳'+spent.toLocaleString(undefined,{minimumFractionDigits:2})+'</strong></div><hr><div class="d-flex justify-content-between"><strong>Net Balance</strong><strong class="text-success">৳'+net.toLocaleString(undefined,{minimumFractionDigits:2})+'</strong></div></div><div class="col-md-4"><h4 class="mb-4 text-success">◷ &nbsp; Trip Timeline</h4><div class="mb-3">● &nbsp; Created</div><div class="mb-3">● &nbsp; Trip Started <span class="float-end text-muted">'+d.start_date+'</span></div><div>● &nbsp; Expected End <span class="float-end text-muted">'+d.end_date+'</span></div></div></div></div></td>';
  row.after(details);toggle.onclick=function(){var open=details.style.display!=='none';details.style.display=open?'none':'table-row';toggle.innerHTML=open?'⌄':'⌃'};
 });
});
</script>
